package com.trampolim.api.education;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.flywaydb.core.Flyway;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.support.JdbcTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;

class AssessmentPostgresTest {
    static JdbcTemplate admin,jdbc;static String schema;AssessmentService service;LearningPerformanceService performance;LearningAccess access;LearningController learning;TransactionTemplate tx;
    String teacherEmail,studentEmail,otherEmail,secondEmail;long teacher,student,other,second,course,subject,module,lesson;UUID q1,q2,a1,a2,b1,b2,skill;
    @BeforeAll static void database(){String url=env("CAPACITA_DB_URL","jdbc:postgresql://localhost:5434/trampolim_capacita_db");String user=env("CAPACITA_DB_USERNAME","trampolim_capacita"),password=env("CAPACITA_DB_PASSWORD","dev_capacita_only");admin=new JdbcTemplate(new DriverManagerDataSource(url,user,password));schema="assessment_test_"+UUID.randomUUID().toString().replace("-","");admin.execute("CREATE SCHEMA "+schema);var source=new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema,user,password);Flyway.configure().dataSource(source).locations("classpath:db/migration-capacita").load().migrate();jdbc=new JdbcTemplate(source);}
    @AfterAll static void cleanup(){if(admin!=null&&schema!=null)admin.execute("DROP SCHEMA "+schema+" CASCADE");}
    @BeforeEach void setup(){teacherEmail=email();studentEmail=email();otherEmail=email();secondEmail=email();teacher=account(teacherEmail);student=account(studentEmail);other=account(otherEmail);second=account(secondEmail);jdbc.update("INSERT INTO learning_account_roles(user_id,role) VALUES (?,'TEACHER'),(?,'TEACHER')",teacher,other);access=new LearningAccess(jdbc);ReflectionTestUtils.setField(access,"bootstrapAdmins","");learning=new LearningController(jdbc,access);service=new AssessmentService(jdbc,access,learning);performance=new LearningPerformanceService(jdbc,access,service);tx=new TransactionTemplate(new JdbcTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));course=((Number)learning.createCourse(teacherEmail,new LearningController.CourseInput("Assessment course","Fixture","Math",null,"PUBLISHED")).get("id")).longValue();subject=jdbc.queryForObject("INSERT INTO learning_subjects(course_id,title) VALUES (?,'Subject') RETURNING id",Long.class,course);module=jdbc.queryForObject("INSERT INTO learning_modules(subject_id,title) VALUES (?,'Module') RETURNING id",Long.class,subject);lesson=jdbc.queryForObject("INSERT INTO learning_lessons(module_id,title,status,media_key,duration_seconds,validation_status) VALUES (?,'Lesson','PUBLISHED',?,180,'READY') RETURNING id",Long.class,module,UUID.randomUUID());q1=UUID.randomUUID();q2=UUID.randomUUID();a1=UUID.randomUUID();a2=UUID.randomUUID();b1=UUID.randomUUID();b2=UUID.randomUUID();skill=UUID.randomUUID();}
    private long account(String email){return jdbc.queryForObject("INSERT INTO student_users(email,password_hash,full_name,education_stage,email_verified,account_status,terms_accepted_at) VALUES (?,'test-only','Private student fixture','HIGH_SCHOOL',TRUE,'ACTIVE',CURRENT_TIMESTAMP) RETURNING id",Long.class,email);}
    private AssessmentService.Definition definition(int pass,int attempts,boolean study,Instant due,boolean changed){return new AssessmentService.Definition("Weighted assessment","Description","Read carefully","Fractions",pass,attempts,due,study,true,true,List.of(new AssessmentService.Question(q1,"MCQ","Question one",3,List.of(new AssessmentService.Option(a1,"Option A"),new AssessmentService.Option(a2,"Option B")),changed?a2:a1,"Feedback one"),new AssessmentService.Question(q2,"MCQ","Question two",1,List.of(new AssessmentService.Option(b1,"Option C"),new AssessmentService.Option(b2,"Option D")),b1,"Feedback two")),List.of(new AssessmentService.Competency(skill,"Fractions","Weighted assessment proof")));}
    private AssessmentService.Input input(AssessmentService.Definition definition,String status,Integer revision){return new AssessmentService.Input(course,subject,module,status,revision,definition);}
    private long create(AssessmentService.Definition definition){var created=tx.execute(status->service.create(teacherEmail,input(definition,"PUBLISHED",null)));return ((Number)created.get("id")).longValue();}
    private UUID start(long id){return (UUID)tx.execute(status->service.start(studentEmail,id)).get("id");}
    private Map<String,String> answers(boolean pass){return Map.of(q1.toString(),(pass?a1:a2).toString(),q2.toString(),b2.toString());}
    private Map<String,Object> submit(UUID attempt,UUID key,boolean pass){return tx.execute(status->service.submit(studentEmail,attempt,new AssessmentService.Submission(key,answers(pass))));}
    @Test void weightedGradingHistoryAndPrivateAnswers()throws Exception{long id=create(definition(75,2,false,null,false));String visible=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(service.detail(studentEmail,id,false));assertFalse(visible.contains("correctOptionId"));assertFalse(visible.contains("Feedback one"));UUID attempt=start(id);assertEquals(attempt,start(id));tx.executeWithoutResult(status->service.draft(studentEmail,attempt,Map.of(q1.toString(),a1.toString())));assertEquals(a1.toString(),((Map<?,?>)service.attempt(studentEmail,attempt,false).get("answers")).get(q1.toString()));var result=submit(attempt,UUID.randomUUID(),true);assertEquals("75.00",result.get("score_percent").toString());assertEquals(true,result.get("passed"));assertEquals(3,((Number)result.get("earned_points")).intValue());assertEquals(1,performance.competencies(studentEmail).size());assertEquals(1,service.history(studentEmail).size());assertEquals(0,service.history(secondEmail).size());assertEquals(75,((Map<?,?>)result.get("criteria")).get("passPercent"));}
    @Test void duplicateConcurrentSubmissionCannotIssueTwoAwards()throws Exception{long id=create(definition(75,2,false,null,false));UUID attempt=start(id),key=UUID.randomUUID();var pool=Executors.newFixedThreadPool(2);try{var jobs=pool.invokeAll(List.<Callable<Map<String,Object>>>of(()->submit(attempt,key,true),()->submit(attempt,key,true)));for(var job:jobs)assertEquals(true,job.get().get("passed"));}finally{pool.shutdownNow();}assertEquals(1,performance.competencies(studentEmail).size());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM learning_assessment_attempts WHERE assessment_id=?",Integer.class,id));assertThrows(ResponseStatusException.class,()->submit(attempt,key,false));assertThrows(ResponseStatusException.class,()->submit(attempt,UUID.randomUUID(),true));}
    @Test void limitsDeadlineAndAnswerManipulationAreRejected(){long id=create(definition(75,2,false,null,false));UUID first=start(id);assertThrows(ResponseStatusException.class,()->tx.execute(status->service.submit(studentEmail,first,new AssessmentService.Submission(UUID.randomUUID(),Map.of(q1.toString(),"forged")))));assertThrows(ResponseStatusException.class,()->tx.execute(status->service.submit(studentEmail,first,new AssessmentService.Submission(UUID.randomUUID(),Map.of(q1.toString(),a1.toString())))));submit(first,UUID.randomUUID(),false);assertTrue(performance.competencies(studentEmail).isEmpty());UUID next=start(id);assertNotEquals(first,next);submit(next,UUID.randomUUID(),false);assertThrows(ResponseStatusException.class,()->start(id));assertEquals(2,service.history(studentEmail).size());long expired=create(definition(75,2,false,Instant.now().minusSeconds(60),false));assertThrows(ResponseStatusException.class,()->start(expired));}
    @Test void studyPrerequisiteDashboardAndEarnedCompetency(){long id=create(definition(75,2,true,null,false));assertThrows(ResponseStatusException.class,()->start(id));jdbc.update("INSERT INTO learning_lesson_progress(student_id,lesson_id,position_seconds,watched_seconds,completed_at) VALUES (?,?,180,180,CURRENT_TIMESTAMP)",student,lesson);assertEquals(0L,performance.dashboard(studentEmail).get("coursesCompleted"));assertEquals(0L,performance.dashboard(studentEmail).get("modulesCompleted"));submit(start(id),UUID.randomUUID(),true);var dashboard=performance.dashboard(studentEmail);assertEquals(1L,dashboard.get("coursesCompleted"));assertEquals(1L,dashboard.get("modulesCompleted"));assertEquals(1L,dashboard.get("lessonsCompleted"));assertEquals(1L,dashboard.get("competenciesEarned"));}
    @Test void newVersionDoesNotRegradeOldAttemptOrOverwriteHistory(){long id=create(definition(75,3,false,null,false));UUID attempt=start(id);tx.executeWithoutResult(status->service.edit(teacherEmail,id,input(definition(100,3,false,null,true),"PUBLISHED",0)));var old=submit(attempt,UUID.randomUUID(),true);assertEquals(true,old.get("passed"));assertEquals(75,((Map<?,?>)old.get("criteria")).get("passPercent"));var next=submit(start(id),UUID.randomUUID(),true);assertEquals(false,next.get("passed"));assertEquals(2,service.history(studentEmail).size());assertEquals(1,performance.competencies(studentEmail).size());assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->service.edit(teacherEmail,id,input(definition(75,3,false,null,false),"PUBLISHED",0))));}
    @Test void permissionsAndUnearnedCompetencyAreProtected(){long id=create(definition(75,2,false,null,false));UUID attempt=start(id);assertThrows(ResponseStatusException.class,()->service.detail(otherEmail,id,true));assertThrows(ResponseStatusException.class,()->tx.execute(status->service.create(studentEmail,input(definition(75,2,false,null,false),"PUBLISHED",null))));assertThrows(ResponseStatusException.class,()->tx.execute(status->service.start(teacherEmail,id)));assertThrows(ResponseStatusException.class,()->service.attempt(secondEmail,attempt,false));assertThrows(ResponseStatusException.class,()->service.report(otherEmail,id));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->performance.present(studentEmail,UUID.randomUUID(),new AssessmentService.Presentation(true,0))));assertThrows(ResponseStatusException.class,()->tx.execute(status->service.submit(secondEmail,attempt,new AssessmentService.Submission(UUID.randomUUID(),answers(true)))));assertEquals(1,service.report(teacherEmail,id).size());}
    @Test void consentedSharingExportAndRevocation(){long id=create(definition(75,2,false,null,false));submit(start(id),UUID.randomUUID(),true);UUID award=(UUID)performance.competencies(studentEmail).get(0).get("id");assertThrows(ResponseStatusException.class,()->tx.execute(status->performance.share(studentEmail,award,false)));tx.executeWithoutResult(status->performance.present(studentEmail,award,new AssessmentService.Presentation(true,3)));assertThrows(ResponseStatusException.class,()->tx.execute(status->performance.export(studentEmail,false)));var exported=tx.execute(status->performance.export(studentEmail,true));assertEquals(1,((List<?>)exported.get("competencies")).size());assertThrows(ResponseStatusException.class,()->tx.execute(status->performance.share(secondEmail,award,true)));String token=(String)tx.execute(status->performance.share(studentEmail,award,true)).get("token");var shared=performance.shared(token);assertFalse(shared.containsKey("student_id"));assertFalse(shared.containsKey("email"));assertEquals(false,shared.get("formalCertificate"));assertNotEquals(token,jdbc.queryForObject("SELECT share_hash FROM learning_competency_awards WHERE id=?",String.class,award));tx.executeWithoutResult(status->performance.revoke(studentEmail,award));assertThrows(ResponseStatusException.class,()->performance.shared(token));}
    @Test void concurrentStartResumesSameAttemptAndDraftCannotAlterSubmittedResult()throws Exception{long id=create(definition(75,1,false,null,false));var pool=Executors.newFixedThreadPool(3);Set<UUID> ids=new HashSet<>();try{for(var job:pool.invokeAll(List.<Callable<UUID>>of(()->start(id),()->start(id),()->start(id))))ids.add(job.get());}finally{pool.shutdownNow();}assertEquals(1,ids.size());UUID attempt=ids.iterator().next();submit(attempt,UUID.randomUUID(),true);assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->service.draft(studentEmail,attempt,answers(false))));}
    private static String email(){return UUID.randomUUID()+"@example.test";}private static String env(String name,String fallback){String value=System.getenv(name);return value==null||value.isBlank()?fallback:value;}
}
